mapper.select:
WITH RECURSIVE product_tree AS ( SELECT , 1 AS tree_depth, CAST(c.parent_code AS TEXT) AS tree_path, ARRAY[c.parent_code, c.child_code] as visited_nodes FROM ${productPartCompTableName} c LEFT JOIN ${productPartTableName} p ON c.parent_code = p.primary_key LEFT JOIN ${productPartTableName} ch ON c.child_code = ch.primary_key WHERE c.enterprise_code = #{enterpriseCode} AND c.parent_code = #{data.parentCode} AND c.delete_flag = false AND c.child_code IS NOT NULL UNION ALL SELECT , pt.tree_depth + 1 AS tree_depth, pt.tree_path || '->' || c.child_code AS tree_path, pt.visited_nodes || c.child_code FROM ${productPartCompTableName} c INNER JOIN product_tree pt ON c.parent_code = pt.child_code AND c.child_code <> ALL(pt.visited_nodes) LEFT JOIN ${productPartTableName} p ON c.parent_code = p.primary_key LEFT JOIN ${productPartTableName} ch ON c.child_code = ch.primary_key WHERE pt.visited_nodes[array_length(pt.visited_nodes,1)] IS NOT NULL AND c.enterprise_code = #{enterpriseCode} AND c.delete_flag = false AND pt.tree_depth <= COALESCE(#{data.treeDepth}, 5) AND c.child_code IS NOT NULL ) SELECT
FROM product_tree WHERE true
AND tree_depth <= #{data.treeDepth}
AND tree_depth <= 5
AND child_code IS NOT NULL;

WITH RECURSIVE product_tree AS ( SELECT , 1 AS tree_depth, CAST(c.parent_code AS TEXT) AS tree_path, ARRAY[c.child_code, c.parent_code] as visited_nodes FROM ${productPartCompTableName} c INNER JOIN ${productPartTableName} p ON c.parent_code = p.primary_key INNER JOIN ${productPartTableName} ch ON c.child_code = ch.primary_key WHERE c.enterprise_code = #{enterpriseCode}
AND c.child_code = #{data.childCode} -- 输入的child_code
AND c.child_code IN
#{item}
AND c.delete_flag = false AND c.parent_code IS NOT NULL UNION ALL SELECT, pt.tree_depth + 1 AS tree_depth, pt.tree_path || '->' || c.parent_code AS tree_path, pt.visited_nodes || c.parent_code FROM ${productPartCompTableName} c INNER JOIN product_tree pt ON c.child_code = pt.parent_code AND c.parent_code <> ALL (pt.visited_nodes) LEFT JOIN ${productPartTableName} p ON c.parent_code = p.primary_key LEFT JOIN ${productPartTableName} ch ON c.child_code = ch.primary_key WHERE c.enterprise_code = #{enterpriseCode}
AND c.child_code = #{data.childCode} -- 输入的child_code
AND c.child_code IN
#{item}
AND c.delete_flag = false AND pt.tree_depth <= COALESCE(#{data.treeDepth}, 5) AND c.parent_code IS NOT NULL) SELECT
FROM product_tree WHERE true
AND tree_depth <= #{data.treeDepth}
AND tree_depth <= 5
AND child_code IS NOT NULL;

SELECT MAX(depth)
FROM ${productPartCompTableName}  
WHERE child_code = #{parentCode}
AND enterprise_code = #{enterpriseCode}
AND delete_flag = false

SELECT
CONCAT(parent_code, '_', parent_attribute) AS key,
COUNT(*) AS count
FROM ${tableName}
WHERE
enterprise_code = #{enterpriseCode}
AND delete_flag = false
AND (

    parent_code = #{condition.parentCode}
    AND parent_attribute = #{condition.parentAttribute}

)
GROUP BY parent_code, parent_attribute, enterprise_code
